import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
  {
    path: 'dashboard',
    data: { section: 'dashboard', label: 'Dashboard', order: 0 },
    loadComponent: () => import('./features/dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'clients',
    data: { section: 'clients', label: 'Clients', order: 1 },
    loadComponent: () => import('./features/clients/clients').then((m) => m.Clients),
  },
  {
    path: 'clients/:id',
    loadComponent: () => import('./features/clients/client-detail').then((m) => m.ClientDetail),
  },
  {
    path: 'clients/:id/statement',
    loadComponent: () => import('./features/invoices/client-statement').then((m) => m.ClientStatement),
  },
  {
    path: 'projects',
    data: { section: 'projects', label: 'Projects', order: 2 },
    loadComponent: () => import('./features/projects/projects').then((m) => m.Projects),
  },
  {
    path: 'invoices',
    data: { section: 'invoices', label: 'Invoices', order: 3 },
    loadComponent: () => import('./features/invoices/invoices').then((m) => m.Invoices),
  },
  {
    path: 'projects/:id',
    loadComponent: () => import('./features/projects/project-detail').then((m) => m.ProjectDetail),
  },
  {
    path: 'projects/:projectId/invoices/:invoiceId',
    loadComponent: () => import('./features/invoices/invoice-detail').then((m) => m.InvoiceDetailPage),
  },
];
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Component } from '@angular/core';

// The base home page (empty). A page is an Angular component like this one, plus one entry in
// app.routes.ts.
@Component({
  selector: 'app-home',
  template: `<p data-testid="home-empty">Nothing here yet.</p>`,
})
export class Home {}
import { Component, computed, inject, signal } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { Client, ClientService } from './client.service';

// Clients page: add a client (name + email) and list all clients, filterable by name; each client
// opens its detail page. A client no longer worked with can be archived: it is kept but left off the
// list and search unless the archived toggle is on, where it can be restored.
@Component({
  selector: 'app-clients',
  imports: [ReactiveFormsModule, RouterLink],
  template: `
    <h1>Clients</h1>

    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="client-form" novalidate>
      <div>
        <label for="client-name">Name</label>
        <input
          id="client-name"
          type="text"
          formControlName="name"
          autocomplete="organization"
          data-testid="client-form-name"
          [attr.aria-invalid]="showError('name')"
          [attr.aria-describedby]="showError('name') ? 'client-name-error' : null"
        />
        @if (showError('name')) {
          <p id="client-name-error" role="alert" data-testid="client-form-name-error">
            Name is required.
          </p>
        }
      </div>
      <div>
        <label for="client-email">Email</label>
        <input
          id="client-email"
          type="email"
          formControlName="email"
          autocomplete="email"
          data-testid="client-form-email"
          [attr.aria-invalid]="showError('email')"
          [attr.aria-describedby]="showError('email') ? 'client-email-error' : null"
        />
        @if (showError('email')) {
          <p id="client-email-error" role="alert" data-testid="client-form-email-error">
            Enter a valid email address.
          </p>
        }
      </div>
      <button type="submit" data-testid="client-form-submit" [disabled]="saving()">Add client</button>
      @if (saveError()) {
        <p role="alert" data-testid="client-form-error">{{ saveError() }}</p>
      }
    </form>

    @if (actionError()) {
      <p role="alert" data-testid="client-archive-error">{{ actionError() }}</p>
    }

    <div>
      <input
        id="clients-show-archived"
        type="checkbox"
        data-testid="clients-show-archived"
        [checked]="showArchived()"
        (change)="toggleArchived()"
      />
      <label for="clients-show-archived">Show archived clients</label>
    </div>

    @if (clients().length === 0) {
      <p data-testid="clients-empty">No clients yet.</p>
    } @else {
      <div role="search">
        <label for="client-search">Search clients by name</label>
        <input
          id="client-search"
          type="search"
          autocomplete="off"
          data-testid="client-search"
          [value]="query()"
          (input)="onSearch($event)"
        />
      </div>
      @if (filteredClients().length === 0) {
        <p role="status" data-testid="clients-no-match">No clients match your search.</p>
      } @else {
        <table data-testid="clients-table">
          <caption>All clients</caption>
          <thead>
            <tr>
              <th scope="col">Name</th>
              <th scope="col">Email</th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (c of filteredClients(); track c.id) {
              <tr [attr.data-testid]="'client-row-' + c.id">
                <td data-testid="client-name">
                  {{ c.name }}
                  @if (c.archived) {
                    <span [attr.data-testid]="'client-archived-' + c.id">(archived)</span>
                  }
                </td>
                <td data-testid="client-email">{{ c.email }}</td>
                <td>
                  <a
                    [routerLink]="['/clients', c.id]"
                    [attr.data-testid]="'client-open-' + c.id"
                    [attr.aria-label]="'Open ' + c.name"
                    >Open</a
                  >
                  @if (c.archived) {
                    <button
                      type="button"
                      [attr.data-testid]="'client-restore-' + c.id"
                      [attr.aria-label]="'Restore ' + c.name"
                      [disabled]="busy() === c.id"
                      (click)="restore(c)"
                    >
                      Restore
                    </button>
                  } @else {
                    <button
                      type="button"
                      [attr.data-testid]="'client-archive-' + c.id"
                      [attr.aria-label]="'Archive ' + c.name"
                      [disabled]="busy() === c.id"
                      (click)="archive(c)"
                    >
                      Archive
                    </button>
                  }
                </td>
              </tr>
            }
          </tbody>
        </table>
      }
    }
  `,
})
export class Clients {
  private readonly service = inject(ClientService);

  protected readonly clients = signal<Client[]>([]);
  protected readonly query = signal('');
  // Case-insensitive name filter; an empty query shows every client.
  protected readonly filteredClients = computed(() => {
    const q = this.query().trim().toLowerCase();
    const list = this.clients();
    return q ? list.filter((c) => c.name.toLowerCase().includes(q)) : list;
  });
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);
  protected readonly showArchived = signal(false);
  protected readonly busy = signal<number | null>(null);
  protected readonly actionError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    email: [
      '',
      [
        Validators.required,
        Validators.email,
        // Validators.email accepts "a@b"; also require a dotted domain (matches the server rule).
        Validators.pattern(/^[^@\s]+@[^@\s]+\.[^@\s]+$/),
        Validators.maxLength(255),
      ],
    ],
  });

  constructor() {
    this.load();
  }

  protected onSearch(event: Event): void {
    this.query.set((event.target as HTMLInputElement).value);
  }

  protected showError(field: 'name' | 'email'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, email } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    this.service.create({ name: name.trim(), email: email.trim() }).subscribe({
      next: (created) => {
        this.clients.update((list) => [...list, created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the client. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected toggleArchived(): void {
    this.showArchived.update((show) => !show);
    this.load();
  }

  protected archive(client: Client): void {
    this.busy.set(client.id);
    this.actionError.set(null);
    this.service.archive(client.id).subscribe({
      next: (archived) => {
        this.clients.update((list) =>
          this.showArchived()
            ? list.map((c) => (c.id === archived.id ? archived : c))
            : list.filter((c) => c.id !== archived.id),
        );
        this.busy.set(null);
      },
      error: () => {
        this.actionError.set(`Could not archive ${client.name}. Please try again.`);
        this.busy.set(null);
      },
    });
  }

  protected restore(client: Client): void {
    this.busy.set(client.id);
    this.actionError.set(null);
    this.service.restore(client.id).subscribe({
      next: (restored) => {
        this.clients.update((list) => list.map((c) => (c.id === restored.id ? restored : c)));
        this.busy.set(null);
      },
      error: () => {
        this.actionError.set(`Could not restore ${client.name}. Please try again.`);
        this.busy.set(null);
      },
    });
  }

  private load(): void {
    this.service.list(this.showArchived()).subscribe((list) => this.clients.set(list));
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

/** The statuses a project can be marked with, in the order they are offered. */
export const PROJECT_STATUSES: { value: ProjectStatus; label: string }[] = [
  { value: 'ACTIVE', label: 'Active' },
  { value: 'ON_HOLD', label: 'On hold' },
  { value: 'FINISHED', label: 'Finished' },
];

export interface Project {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
}

/** A project's budget, what has been invoiced against it, and what is left; null when no budget is set. */
export interface ProjectBudget {
  budget: number | null;
  invoiced: number;
  remaining: number | null;
}

export interface NewProject {
  name: string;
  clientId: number;
  status: ProjectStatus;
}

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private readonly http = inject(HttpClient);

  list(
    includeArchived = false,
    tagId: number | null = null,
    status: ProjectStatus | null = null,
  ): Observable<Project[]> {
    const params: Record<string, string | number | boolean> = { includeArchived };
    if (tagId !== null) {
      params['tagId'] = tagId;
    }
    if (status !== null) {
      params['status'] = status;
    }
    return this.http.get<Project[]>('/api/projects', { params });
  }

  listForClient(clientId: number, includeAll = false): Observable<Project[]> {
    return this.http.get<Project[]>(`/api/clients/${clientId}/projects`, {
      params: { includeAll },
    });
  }

  get(id: number): Observable<Project> {
    return this.http.get<Project>(`/api/projects/${id}`);
  }

  create(project: NewProject): Observable<Project> {
    return this.http.post<Project>('/api/projects', project);
  }

  changeStatus(id: number, status: ProjectStatus): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/status`, { status });
  }

  budget(id: number): Observable<ProjectBudget> {
    return this.http.get<ProjectBudget>(`/api/projects/${id}/budget`);
  }

  setBudget(id: number, budget: number | null): Observable<ProjectBudget> {
    return this.http.put<ProjectBudget>(`/api/projects/${id}/budget`, { budget });
  }

  archive(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/archive`, null);
  }

  restore(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/restore`, null);
  }
}
